        float2 scaleVec;
        scaleVec = float2(amzp_scale*amzp_stretch.x,amzp_scale*amzp_stretch.y);
        satriyaid /= scaleVec;
     float4 fragColor;
         float2 uv = satriyaid;
         float t = floor(iTime*0.33);
         float color = clamp(float4(float3((heightmap(float3(uv.xy*5.0,t)*0.02)-1.0)),1.0).r,0.0,1.0);
            if (color<0.1) fragColor=float4(0.77,0.90,0.98,1.0);
            else
            if (color<0.2) fragColor=float4(0.82,0.92,0.99,1.0);
            else
